// Simple neural network operations
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

double relu(double x) {
    return x > 0 ? x : 0;
}

// Matrix-vector multiplication
std::vector<double> matMul(const std::vector<std::vector<double>>& W, const std::vector<double>& x) {
    std::vector<double> result(W.size(), 0.0);
    for (size_t i = 0; i < W.size(); i++) {
        for (size_t j = 0; j < x.size(); j++) {
            result[i] += W[i][j] * x[j];
        }
    }
    return result;
}

// Vector addition
std::vector<double> add(const std::vector<double>& a, const std::vector<double>& b) {
    std::vector<double> result(a.size());
    for (size_t i = 0; i < a.size(); i++) {
        result[i] = a[i] + b[i];
    }
    return result;
}

// ReLU activation on vector
std::vector<double> reluVec(const std::vector<double>& x) {
    std::vector<double> result(x.size());
    for (size_t i = 0; i < x.size(); i++) {
        result[i] = relu(x[i]);
    }
    return result;
}

// Load weights from JSON file
void loadWeights(const std::string& filename, 
                 std::vector<std::vector<double>>& input_weights,
                 std::vector<double>& input_bias,
                 std::vector<std::vector<double>>& hidden_weights,
                 std::vector<double>& hidden_bias,
                 std::vector<std::vector<double>>& output_weights,
                 std::vector<double>& output_bias) {
    std::ifstream file(filename);
    std::string content((std::istreambuf_iterator<char>(file)),
                        std::istreambuf_iterator<char>());
    file.close();

    cJSON* json = cJSON_Parse(content.c_str());
    if (!json) {
        std::cerr << "Failed to parse JSON" << std::endl;
        return;
    }

    cJSON* input_w = cJSON_GetObjectItem(json, "input_layer.weight");
    cJSON* input_b = cJSON_GetObjectItem(json, "input_layer.bias");
    cJSON* hidden_w = cJSON_GetObjectItem(json, "hidden_layer.weight");
    cJSON* hidden_b = cJSON_GetObjectItem(json, "hidden_layer.bias");
    cJSON* output_w = cJSON_GetObjectItem(json, "output_layer.weight");
    cJSON* output_b = cJSON_GetObjectItem(json, "output_layer.bias");

    // Load input layer weights (16x256)
    input_weights.resize(256, std::vector<double>(16));
