        cJSON* row = cJSON_GetArrayItem(input_w, i);
        for (int j = 0; j < 16; j++) {
            input_weights[i][j] = cJSON_GetArrayItem(row, j)->valuedouble;
        }
    }

    // Load input layer bias (256)
    input_bias.resize(256);
    for (int i = 0; i < 256; i++) {
        input_bias[i] = cJSON_GetArrayItem(input_b, i)->valuedouble;
    }

