    hidden_weights.resize(256, std::vector<double>(256));
    for (int i = 0; i < 256; i++) {
        cJSON* row = cJSON_GetArrayItem(hidden_w, i);
        for (int j = 0; j < 256; j++) {
            hidden_weights[i][j] = cJSON_GetArrayItem(row, j)->valuedouble;
        }
    }

    // Load hidden layer bias (256)
    hidden_bias.resize(256);
    for (int i = 0; i < 256; i++) {
        hidden_bias[i] = cJSON_GetArrayItem(hidden_b, i)->valuedouble;
    }

    // Load output layer weights (10x256)
    output_weights.resize(10, std::vector<double>(256));
    for (int i = 0; i < 10; i++) {
        cJSON* row = cJSON_GetArrayItem(output_w, i);
        for (int j = 0; j < 256; j++) {
            output_weights[i][j] = cJSON_GetArrayItem(row, j)->valuedouble;
        }
    }

    // Load output layer bias (10)
    output_bias.resize(10);
    for (int i = 0; i < 10; i++) {
        output_bias[i] = cJSON_GetArrayItem(output_b, i)->valuedouble;
    }

    cJSON_Delete(json);
}

